      "id": "03-Compute-q17",
      "moduleId": "03-Compute",
      "questionNumber": 17,
      "scenario": "An Auto Scaling group needs to ensure that newly launched instances are ready to serve traffic before receiving requests. What should be configured?",
      "isMultiSelect": false,
